-- ---------- volunteer totals (derived from attendance above) ----------
UPDATE volunteers v SET total_hours = (SELECT COALESCE(SUM(a.hours_awarded),0) FROM attendance_records a WHERE a.volunteer_id = v.volunteer_id AND a.status = 'Completed'), completed_events_count = (SELECT COUNT(*) FROM attendance_records a WHERE a.volunteer_id = v.volunteer_id AND a.status = 'Completed') WHERE v.user_id IN (SELECT user_id FROM users WHERE email LIKE '%@sample.communityservice.test');

