-- ---------- SYSTEM POLICIES (in addition to the two the app seeds itself) ----------
INSERT INTO system_policies (policy_title, policy_content, version, effective_date, last_updated_by, is_active)
SELECT 'Privacy & Data Protection Policy', 'We collect only the personal information needed to run volunteering programmes (name, contact details, attendance and hours). Data is used for platform operations and certificates, is not sold, and is handled in line with POPIA. Users may ask for their data to be corrected or removed.', '1.0', CURRENT_DATE, (SELECT user_id FROM users WHERE email = 'thandi.mokoena@sample.communityservice.test'), TRUE FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM system_policies WHERE policy_title = 'Privacy & Data Protection Policy');
INSERT INTO system_policies (policy_title, policy_content, version, effective_date, last_updated_by, is_active)
SELECT 'Volunteer Safety Policy', 'Volunteers must follow NGO safety briefings, use provided protective equipment, and report incidents immediately. Volunteers under 18 need guardian consent where the event requires it.', '1.0', CURRENT_DATE, (SELECT user_id FROM users WHERE email = 'thandi.mokoena@sample.communityservice.test'), TRUE FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM system_policies WHERE policy_title = 'Volunteer Safety Policy');
INSERT INTO system_policies (policy_title, policy_content, version, effective_date, last_updated_by, is_active)
SELECT 'Event Cancellation Policy', 'NGOs may cancel an event for safety or capacity reasons. Applicants are notified, and no hours are awarded for cancelled events. Volunteers should withdraw at least 24 hours before an event if they cannot attend.', '1.0', CURRENT_DATE, (SELECT user_id FROM users WHERE email = 'thandi.mokoena@sample.communityservice.test'), TRUE FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM system_policies WHERE policy_title = 'Event Cancellation Policy');
INSERT INTO system_policies (policy_title, policy_content, version, effective_date, last_updated_by, is_active)
SELECT 'Hours & Certificate Policy', 'Volunteer hours are awarded only after an NGO confirms attendance. Certificates are issued for completed events and carry a unique certification number.', '1.0', CURRENT_DATE, (SELECT user_id FROM users WHERE email = 'thandi.mokoena@sample.communityservice.test'), TRUE FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM system_policies WHERE policy_title = 'Hours & Certificate Policy');

SELECT 'Seed data loaded.' AS result;
